const { test, expect } = require('@playwright/test');

test.describe('Todo App Tests', () => {
  test.beforeAll(async () => {
    // Start the app server if not already running
    const { spawn } = require('child_process');
    const server = spawn('npm', ['start'], {
      cwd: '/workspace/todo-app',
      stdio: 'pipe',
      shell: true
    });

    // Wait for server to start
    await new Promise((resolve) => {
      server.stdout.on('data', (data) => {
        if (data.toString().includes('ready on')) {
          resolve();
        }
      });
      setTimeout(resolve, 5000); // Fallback timeout
    });

    // Kill any existing process on port 3000
    const { exec } = require('child_process');
    exec('lsof -ti:3000 | xargs kill -9 2>/dev/null || true', (error) => {});
  });

  test.afterAll(async () => {
    // Kill the process on port 3000
    const { exec } = require('child_process');
    exec('lsof -ti:3000 | xargs kill -9 2>/dev/null || true');
  });

  test('should load the todo app', async ({ page }) => {
    await page.goto('http://localhost:3000');

    // Verify the app title is present
    await expect(page.locator('[data-testid="app-title"]')).toBeVisible();

    // Verify initial todo list exists
    await expect(page.locator('[data-testid="todo-list"]')).toBeVisible();

    // Verify initial todo count
    await expect(page.locator('[data-testid="todo-count"]')).toContainText('Total todos: 1');

    // Verify initial todo item text
    await expect(page.locator('[data-testid="todo-list"] li')).toHaveCount(1);
  });

  test('should add a new todo', async ({ page }) => {
    await page.goto('http://localhost:3000');

    // Clear initial todo
    await page.locator('[data-testid="delete-1"]').click();
    await expect(page.locator('[data-testid="todo-list"] li')).toHaveCount(0);

    // Enter new todo text
    await page.locator('[data-testid="todo-input"]').fill('Test Todo Item');

    // Click add button
    await page.locator('[data-testid="add-button"]').click();

    // Verify new todo was added
    await expect(page.locator('[data-testid="todo-list"] li')).toHaveCount(1);
    await expect(page.locator('[data-testid="todo-list"] li span')).toHaveText('Test Todo Item');

    // Verify todo count updated
    await expect(page.locator('[data-testid="todo-count"]')).toContainText('Total todos: 1');
  });

  test('should toggle todo completion status', async ({ page }) => {
    await page.goto('http://localhost:3000');

    // Add a new todo
    await page.locator('[data-testid="todo-input"]').fill('Complete Me');
    await page.locator('[data-testid="add-button"]').click();

    // Verify initial state - not completed
    const todo = page.locator('[data-testid="todo-list"] li');
    await expect(todo).not.toHaveClass('completed');

    // Click complete button
    await page.locator('[data-testid="complete-unique-id"]').first().click();

    // Verify todo is now completed
    await expect(todo).toHaveClass('completed');
    await expect(page.locator('[data-testid="todo-list"] li span')).toHaveCSS('text-decoration', 'line-through');

    // Click complete again to undo
    await page.locator('[data-testid="complete-unique-id"]').first().click();

    // Verify todo is no longer completed
    await expect(todo).not.toHaveClass('completed');
    await expect(page.locator('[data-testid="todo-list"] li span')).not.toHaveCSS('text-decoration', 'line-through');
  });

  test('should delete a todo', async ({ page }) => {
    await page.goto('http://localhost:3000');

    // Add a new todo
    await page.locator('[data-testid="todo-input"]').fill('Delete This');
    await page.locator('[data-testid="add-button"]').click();

    // Verify todo exists
    await expect(page.locator('[data-testid="todo-list"] li')).toHaveCount(2);

    // Click delete button on the newly added todo
    const deleteButtons = page.locator('[data-testid^="delete-"]').filter({ hasText: 'Delete This' }).locator('button');
    await deleteButtons.click();

    // Verify todo was deleted
    await expect(page.locator('[data-testid="todo-list"] li')).toHaveCount(1);

    // Verify todo count updated
    await expect(page.locator('[data-testid="todo-count"]')).toContainText('Total todos: 1');
  });

  test('should handle multiple todos', async ({ page }) => {
    await page.goto('http://localhost:3000');

    // Clear initial todo
    await page.locator('[data-testid="delete-1"]').click();

    // Add multiple todos
    const todosToAdd = ['Todo A', 'Todo B', 'Todo C'];
    for (const todoText of todosToAdd) {
      await page.locator('[data-testid="todo-input"]').fill(todoText);
      await page.locator('[data-testid="add-button"]').click();
    }

    // Verify all todos are present
    await expect(page.locator('[data-testid="todo-list"] li')).toHaveCount(3);
    await expect(page.locator('[data-testid="todo-count"]')).toContainText('Total todos: 3');

    // Complete the first todo
    await page.locator('[data-testid="complete-unique-id"]').first().click();
    await expect(page.locator('[data-testid="todo-list"] li')).toHaveCount(3);

    // Delete the second todo
    await page.locator('[data-testid="delete-unique-id"]').nth(1).click();
    await expect(page.locator('[data-testid="todo-list"] li')).toHaveCount(2);
    await expect(page.locator('[data-testid="todo-count"]')).toContainText('Total todos: 2');
  });
});
